import{z as o,x as i,o as A,c as d,q as l,j as t,D as e,d as a,s,S as n,b as B}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"私有评测的建设","description":"","frontmatter":{"title":"私有评测的建设","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/ef-private-eval-build.md","filePath":"llm/ef-private-eval-build.md","lastUpdated":1791413859000}'),m={name:"llm/ef-private-eval-build.md"};function p(h,E,F,D,f,u){const r=i("Mermaid");return A(),d("div",null,[E[2]||(E[2]=l('<h1 id="私有评测的建设" tabindex="-1">私有评测的建设 <a class="header-anchor" href="#私有评测的建设" aria-label="Permalink to &quot;私有评测的建设&quot;">​</a></h1><div class="epigraph"><p>公开卷给你与文献对表的坐标，自家卷给你产品分布上的真话；私有评测是一门治理工程——渠道、分层、盲库、版本与权限，缺一样，数字就只是内部舆论。</p><footer>—— 据 lm-evaluation-harness 口径、模型卡与报告规范，以及本课程各评测课协议整理</footer></div><p><a href="/llm/ef-statistical-power">上一课</a>定了样本量与资格线，卷子本身还都是公开卷。本课转向自家卷的建设：怎么把产品日志、专家经验变成分层、可审计、能进门禁的私有评测。<a href="/llm/synthetic-eval-sets">合成评测集</a>写过造题，<a href="/llm/eval-contamination">去污染</a>写过剪泄漏，<a href="/llm/aeval-reporting-standard">报告规范</a>写过五件套；本课补的是把它们组织成一个<strong>可持续的机构能力</strong>：谁供题、谁维护、谁能看、多久换血。下一课的组合策略默认私有评测已按本课建成。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>只有公开卷的团队会遇到三面墙。一是<strong>分布墙</strong>：榜单分数与自家产品表现脱节——用户问的是退换货与并发故障，卷子考的是奥数与历史；<a href="/llm/arena-hard">Arena-Hard</a> 课已经警告过「与 Arena 相关」不迁移到你的提示分布。二是<strong>背题墙</strong>：公开卷进训练语料只是时间问题，分数越跑越好看而产品没变。三是<strong>治理墙</strong>：私有题散在个人 notebook 里，改一句题面没人记录，三次会议后没人说得清「上季度那 2 个点的提升」是在哪张卷、哪个版本上测的。<span class="marginnote">「盲测库」可以类比药检的 B 瓶样本：平时封存、谁都不许碰，只在正式发布门禁时开封使用。训练组连题目都看不到，模型就没法提前背题——它防的正是「训练卷分涨了，产品一点没变」这类自我欺骗。</span>私有评测要解决的就是这三堵墙，而第三堵最贵。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>渠道四路</strong>：产品日志（脱敏后按失败信号抽样——低采纳率、改写重试、用户投诉）、客服工单与内部专家手写（覆盖日志里没有的长尾与高危域）、受控合成（按<a href="/llm/synthetic-eval-sets">合成评测集</a>口径造量并验证难度）、公开卷内化（重写题面做平行卷，用于与文献锚定）。<strong>分层三级</strong>：烟雾集（分钟级、跑在每次提交上，只抓回归不测能力）、回归集（小时级、每夜或每版本，主门禁在此）、盲测库（不进日常循环、训练组不可读，只在发布门禁解封）。<strong>治理五条</strong>：每张卷有所有者与变更审批；题面、判定器、协议哈希一起版本化；分数绑<a href="/llm/aeval-reporting-standard">五件套</a>入库；脱敏与用户同意走隐私清单，PII 不进题面；<span class="marginnote">PII 就是个人身份信息：姓名、手机号、身份证号、住址都算。题面入库前要把「张三 138xxxx 投诉物流慢」改写成「[用户] 投诉物流慢」，否则评测集本身就是一份泄漏的用户隐私库——评测数据一旦外流，后果与生产数据库泄露同级。</span>负结果与失败题归档可检索。</p>',7)),(A(),t(n,null,{default:e(()=>[s(r,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20LOG%5B%22%E4%BA%A7%E5%93%81%E6%97%A5%E5%BF%97%E8%84%B1%E6%95%8F%E6%8A%BD%E6%A0%B7%22%5D%20--%3E%20MIX%5B%22%E9%A2%98%E7%9B%AE%E6%B1%A0%22%5D%0A%20%20EXP%5B%22%E4%B8%93%E5%AE%B6%E6%89%8B%E5%86%99%E4%B8%8E%E5%B7%A5%E5%8D%95%22%5D%20--%3E%20MIX%0A%20%20SYN%5B%22%E5%8F%97%E6%8E%A7%E5%90%88%E6%88%90%E8%A1%A5%E9%87%8F%22%5D%20--%3E%20MIX%0A%20%20MIX%20--%3E%20S1%5B%22%E7%83%9F%E9%9B%BE%E9%9B%86%EF%BC%9A%E5%88%86%E9%92%9F%E7%BA%A7%22%5D%0A%20%20MIX%20--%3E%20S2%5B%22%E5%9B%9E%E5%BD%92%E9%9B%86%EF%BC%9A%E6%AF%8F%E5%A4%9C%E4%B8%BB%E9%97%A8%E7%A6%81%22%5D%0A%20%20MIX%20--%3E%20S3%5B%22%E7%9B%B2%E6%B5%8B%E5%BA%93%EF%BC%9A%E8%AE%AD%E7%BB%83%E7%BB%84%E4%B8%8D%E5%8F%AF%E8%AF%BB%22%5D%0A%20%20S1%20--%3E%20CI%5B%22CI%20%E6%8B%A6%E5%9B%9E%E5%BD%92%22%5D%0A%20%20S2%20--%3E%20GATE%5B%22%E7%89%88%E6%9C%AC%E9%97%A8%E7%A6%81%E4%B8%8E%E5%89%96%E9%9D%A2%22%5D%0A%20%20S3%20--%3E%20GATE%0A%20%20GATE%20--%3E%20REF%5B%22%E5%AE%9A%E6%9C%9F%E6%8D%A2%E8%A1%80%E4%B8%8E%E9%80%80%E5%BD%B9%EF%BC%8C%E7%89%88%E6%9C%AC%E7%95%99%E6%A1%A3%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B("h2",{id:"机制",tabindex:"-1"},[a("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=B("p",null,[a("私有卷的价值机制是"),B("strong",null,"分布对齐"),a("：题抽样框与产品请求分布同源，分数的变化才能读成产品体验的变化；代价是失去外部对表，所以要留一条公开平行卷当锚——两边名次分叉时信自家卷，但要把分叉本身记档，它常常指出私有卷的抽样偏差。盲库的机制是"),B("strong",null,"隔离 Goodhart"),a("：训练能看见的卷子迟早被拟合，把发布门禁放进训练组不可读的库，拟合就失去了目标；盲库定期换血，退役的题降级进回归集继续服役。日志循环的机制性偏差要主动纠：日志只见幸存会话与不满用户，沉默的满意用户不在抽样里——按会话类型分层抽样，并接受「私有卷测的是表达过的不满」这一边界。")],-1)),(A(),t(n,null,{default:e(()=>[s(r,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20TD%0A%20%20U%5B%22%E7%9C%9F%E5%AE%9E%E7%94%A8%E6%88%B7%E8%AF%B7%E6%B1%82%E5%85%A8%E8%B2%8C%22%5D%20--%3E%20A%5B%22%E6%BB%A1%E6%84%8F%E7%94%A8%E6%88%B7%3A%20%E6%B2%89%E9%BB%98%3Cbr%2F%3E%E4%B8%8D%E8%BF%9B%E6%97%A5%E5%BF%97%22%5D%0A%20%20U%20--%3E%20B%5B%22%E4%B8%8D%E6%BB%A1%E7%94%A8%E6%88%B7%3A%20%E6%94%B9%E5%86%99%20%E9%87%8D%E8%AF%95%20%E6%8A%95%E8%AF%89%3Cbr%2F%3E%E8%BF%9B%E5%A4%B1%E8%B4%A5%E4%BF%A1%E5%8F%B7%E6%8A%BD%E6%A0%B7%22%5D%0A%20%20B%20--%3E%20S%5B%22%E6%8C%89%E4%BF%A1%E5%8F%B7%E6%8A%BD%E5%87%BA%E7%9A%84%E9%A2%98%E7%9B%AE%E6%B1%A0%22%5D%0A%20%20S%20--%3E%20BIAS%5B%22%E5%9B%BA%E6%9C%89%E5%81%8F%E5%B7%AE%3A%20%E5%8F%AA%E6%B5%8B%E3%80%8E%E8%A1%A8%E8%BE%BE%E8%BF%87%E7%9A%84%E4%B8%8D%E6%BB%A1%E3%80%8F%3Cbr%2F%3E%E6%BB%A1%E6%84%8F%E7%94%A8%E6%88%B7%E7%9A%84%E9%97%AE%E9%A2%98%E6%B2%A1%E8%A2%AB%E6%B5%8B%22%5D%0A%20%20FIX%5B%22%E7%BA%A0%E6%AD%A3%3A%20%E6%8C%89%E4%BC%9A%E8%AF%9D%E7%B1%BB%E5%9E%8B%E5%88%86%E5%B1%82%E6%8A%BD%E6%A0%B7%3Cbr%2F%3E%E5%81%8F%E5%B7%AE%E5%86%99%E8%BF%9B%E8%BE%B9%E7%95%8C%E5%A3%B0%E6%98%8E%22%5D%20-.-%3E%20S%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=l('<p><span class="marginnote">换血节奏比换血数量重要：盲库每年固定解封一两次，其余时间对训练侧只存在「存在性」，不泄露题面。解封后的分数与历史同表比较时，注明盲库版本。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>私有卷没有免费的午餐：小卷子撞上<a href="/llm/ef-statistical-power">功效</a>约束，两个点的差可能测不动，别用小样本给大结论。脱敏会改变难度与语言分布，判定器在脱敏文本上的行为要单独验。组织成本是真实成本：没有所有者的卷子半年就烂，所有者离职要有交接清单。私有分数也不进对外宣传——它没有第三方可复核性，对外仍用<a href="/llm/model-cards">模型卡</a>口径与公开卷说话。<span class="marginnote">初学者容易以为「自家卷子分数高就能写进宣传稿」。实际私有卷没有第三方可复核性：题目不公开、判定器自定，数字只对内有效——不是自家数字不好，而是外人无法验证。对外宣传仍要走公开卷与模型卡口径，内外两套各说各的合法范围。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>私有评测解决三堵墙：分布对齐、背题、治理；治理最贵也最容易被跳过。</li><li>渠道四路：日志抽样、专家手写、受控合成、公开平行卷锚定。</li><li>分层三级：烟雾抓回归、回归做门禁、盲库防拟合；训练组不可读盲库。</li><li>分数绑五件套与协议哈希；负结果归档，版本留档可追溯。</li><li>出处：据 lm-evaluation-harness 口径、模型卡与报告规范，及本课程各评测课协议整理。</li></ul>',5))])}const g=o(m,[["render",p]]);export{C as __pageData,g as default};
